window.HOEREN_TESTS[45] = {"id":"am-bahnhof","name":"Am Bahnhof","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Achtung Reisende: Der ICE 723 nach Hamburg fährt heute nicht von Gleis 5, sondern von Gleis 12. Nicht Gleis 2, wirklich Gleis 12, bitte aufpassen. Wir bitten alle Fahrgäste, zum neuen Gleis zu gehen. Die Abfahrt ist pünktlich um 14 Uhr 30. Wir entschuldigen uns für die Umstände. Vielen Dank. Bitte beeilen Sie sich ein bisschen.","gender":"f","q":"Von welchem Gleis fährt der Zug?","opts":["Gleis 12.","Gleis 5.","Gleis 2."],"correct":0},{"transcript":"Hallo Lisa, hier ist Anna. Also, mein Zug ist verspätet — komme zwei Stunden später. Statt 16 Uhr bin ich erst um 18 Uhr da. Sorry! Um 20 Uhr wäre zu spät, aber 18 Uhr klappt sicher. Geh nicht hungrig — iss schon. Ich nehme dann später was im Restaurant. Hol mich aber bitte ab. Bis dann!","gender":"f","q":"Wann kommt Anna?","opts":["16 Uhr.","20 Uhr.","18 Uhr."],"correct":2},{"transcript":"Liebe Reisende: Die Bahnhofs-Information ist nicht mehr im ersten Stock, sondern direkt am Haupteingang. Nicht im Keller und nicht mehr oben, direkt am Eingang. Geöffnet von 6 bis 22 Uhr täglich. Tickets, Auskunft, Lost-and-Found — alles dort. Wir haben das geändert für bessere Erreichbarkeit. Vielen Dank für Ihre Aufmerksamkeit.","gender":"m","q":"Wo ist die Information jetzt?","opts":["Im ersten Stock.","Am Haupteingang.","Im Keller."],"correct":1},{"transcript":"Hi Markus, hier ist Tom. Ich habe mein Bahnticket verloren! Nicht vergessen, wirklich verloren. Der Zug ist zum Glück noch nicht weg. Komme nicht in den Zug. Muss neues kaufen, kostet 80 Euro. Ärgerlich! Bin später zu dir, hole Ticket erst. Ruf mich an. Vielleicht hast du Idee. Sonst halt teurer. Stress total.","gender":"m","q":"Was ist passiert?","opts":["Tom hat Ticket verloren.","Tom hat Ticket vergessen.","Der Zug ist weg."],"correct":0},{"transcript":"Achtung am Bahnhof: Wegen Bauarbeiten ist der Aufzug zum Gleis 8 außer Betrieb. Gleis 8 ist offen, nur der Aufzug ist kaputt. Reisende mit Koffern oder Kinderwagen können den Aufzug am Gleis 6 nehmen, dann über die Brücke gehen. Es dauert 5 Minuten länger. Wir entschuldigen uns für die Umstände.","gender":"f","q":"Was ist das Problem?","opts":["Brücke gesperrt.","Aufzug Gleis 8 kaputt.","Gleis 8 geschlossen."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer fährt wohin? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Anzeige im Bahnhof zeigt schon die nächsten Züge."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Jeder fährt in eine andere Richtung. Die Fahrkarten habe ich hier."},{"speaker":"Lukas","gender":"m","text":"Mein Zug geht nach Berlin. Freitag früh bin ich schon unterwegs."},{"speaker":"Lisa","gender":"f","text":"In zwei Stunden bist du da. Das ist wirklich bequem."},{"speaker":"Lukas","gender":"m","text":"Fährt noch jemand von uns nach Leipzig?"},{"speaker":"Lisa","gender":"f","text":"Nein. Nach Leipzig fährt keiner."},{"speaker":"Lukas","gender":"m","text":"Deine Fahrkarte liegt ganz oben in meiner Hand."},{"speaker":"Lisa","gender":"f","text":"Ich steige nach Hamburg ein. Am Samstag kochen wir dort bei Freunden."},{"speaker":"Lukas","gender":"m","text":"Tom hat am Wochenende ein lautes Konzert im Westen."},{"speaker":"Lisa","gender":"f","text":"Tom hat eine Fahrkarte nach Köln. Die Gruppe spielt am Samstagabend."},{"speaker":"Lukas","gender":"m","text":"Sara ist eine ganze Woche bei ihrer Familie."},{"speaker":"Lisa","gender":"f","text":"Sara reist nach München. Ihre Oma backt schon einen Kuchen."},{"speaker":"Lukas","gender":"m","text":"Steht Stuttgart auch auf der Liste?"},{"speaker":"Lisa","gender":"f","text":"Nein. Stuttgart steht auch nicht auf der Liste."},{"speaker":"Lukas","gender":"m","text":"Tim macht ein langes Praktikum weiter im Osten."},{"speaker":"Lisa","gender":"f","text":"Tim fährt bis nach Dresden. Er bleibt dort einen Monat."},{"speaker":"Lukas","gender":"m","text":"Dann wünsche ich euch eine gute Fahrt."},{"speaker":"Lisa","gender":"f","text":"Wir schreiben, wenn wir angekommen sind."}],"options":[{"letter":"a","text":"Leipzig"},{"letter":"b","text":"Stuttgart"},{"letter":"c","text":"München"},{"letter":"d","text":"Hamburg"},{"letter":"e","text":"Frankfurt"},{"letter":"f","text":"Berlin"},{"letter":"g","text":"Dresden"},{"letter":"h","text":"Köln"},{"letter":"i","text":"Nürnberg"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"h"},{"person":"Sara","correct":"c"},{"person":"Tim","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Reisender","gender":"m","text":"Guten Tag! Eine Fahrkarte nach München, bitte, hin und zurück, für morgen."},{"speaker":"Verkäuferin","gender":"f","text":"Gerne! Erste oder zweite Klasse? Spezial-Klasse haben wir leider nicht."},{"speaker":"Reisender","gender":"m","text":"Was kostet die erste Klasse?"},{"speaker":"Verkäuferin","gender":"f","text":"120 Euro. Zweite Klasse kostet nur 80 Euro, viel billiger."},{"speaker":"Reisender","gender":"m","text":"Dann nehme ich die zweite Klasse, danke! Auf Wiedersehen!"}],"q":"Welche Klasse nimmt der Reisende?","opts":["Erste Klasse.","Spezial-Klasse.","Zweite Klasse."],"correct":2},{"lines":[{"speaker":"Reisende","gender":"f","text":"Wie lange dauert die Fahrt nach Frankfurt mit dem ICE?"},{"speaker":"Schaffner","gender":"m","text":"Etwa 2 Stunden 30, wenn alles pünktlich ist."},{"speaker":"Reisende","gender":"f","text":"Und mit dem Regional-Zug? Auch nur eine Stunde?"},{"speaker":"Schaffner","gender":"m","text":"Nein, eine Stunde sicher nicht. Regional dauert 4 Stunden, aber günstiger."},{"speaker":"Reisende","gender":"f","text":"Gut, dann nehme ich den ICE. Danke für die Auskunft!"}],"q":"Wie lange dauert ICE?","opts":["Eine Stunde.","4 Stunden.","2 Stunden 30."],"correct":2},{"lines":[{"speaker":"Tochter","gender":"f","text":"Mama, ich finde Papa nicht! Wo ist er?"},{"speaker":"Mutter","gender":"f","text":"Bleib ruhig. Wo sollten wir warten, am Gleis oder im Café?"},{"speaker":"Tochter","gender":"f","text":"Beim Café! Da haben wir uns verabredet."},{"speaker":"Mutter","gender":"f","text":"Oder bei der Information? Nein, wir gehen zum Café. Er sucht uns sicher auch."},{"speaker":"Tochter","gender":"f","text":"Ja, schnell zum Café! Da ist Papa schon!"}],"q":"Wohin gehen sie?","opts":["Zum Café.","Zum Gleis.","Zur Information."],"correct":0},{"lines":[{"speaker":"Tourist","gender":"m","text":"Entschuldigung, wo ist die Gepäck-Aufbewahrung?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Im Untergeschoss, neben den Toiletten. Folgen Sie den Schildern."},{"speaker":"Tourist","gender":"m","text":"Nicht im ersten Stock und nicht am Eingang?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Genau, nur im Untergeschoss. 5 Euro pro Tag und Koffer."},{"speaker":"Tourist","gender":"m","text":"Gut, danke! Dann gehe ich gleich nach unten mit den Koffern. Bis später!"}],"q":"Wo ist die Aufbewahrung?","opts":["Im ersten Stock.","Untergeschoss.","Am Eingang."],"correct":1},{"lines":[{"speaker":"Reisender","gender":"m","text":"Entschuldigung, ist hier noch frei? Oder muss ich stehen?"},{"speaker":"Frau","gender":"f","text":"Eigentlich ist der Platz reserviert. Aber mein Mann sitzt weiter hinten."},{"speaker":"Reisender","gender":"m","text":"Soll ich mir einen anderen Platz suchen?"},{"speaker":"Frau","gender":"f","text":"Nein, bleiben Sie! Sie können sich hier setzen, kein Problem."},{"speaker":"Reisender","gender":"m","text":"Vielen Dank! Das ist sehr nett von Ihnen."}],"q":"Was macht der Reisende?","opts":["Findet anderen Platz.","Setzt sich da.","Steht."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Hubert, einer Schaffnerin bei der Deutschen Bahn. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Hubert, Sie arbeiten seit 18 Jahren als Schaffnerin. Wie sind Sie dazu gekommen?"},{"speaker":"Hubert","gender":"f","text":"Ich wollte etwas mit Reisen machen, aber nicht als Pilotin oder Stewardess — Flugzeug-Angst! Bahn war perfekt. Habe Ausbildung gemacht, dann gleich gestartet. Ich liebe Züge, schon seit meiner Kindheit."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie genau im Zug?"},{"speaker":"Hubert","gender":"f","text":"Tickets kontrollieren, Auskunft geben, manchmal Konflikte schlichten. Notfälle behandeln — wenn jemand krank wird, zum Beispiel. Auch Sicherheit beachten. Mehr als nur Tickets prüfen."},{"speaker":"Reporter","gender":"m","text":"Was sind die häufigsten Probleme?"},{"speaker":"Hubert","gender":"f","text":"Reisende ohne Ticket — sie sagen, vergessen oder verloren. Oft Lüge. Strafe 60 Euro. Auch Streit über Sitzplätze — Reservierungen verstehen viele nicht. Und betrunkene Fahrgäste am Wochenende — die schwierigsten."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste?"},{"speaker":"Hubert","gender":"f","text":"Verspätungen erklären. Wir können nichts dafür, aber Fahrgäste sind sauer. Manche sehr unfreundlich. Geduld brauchen wir viel. Auch lange Schichten — manchmal 12 Stunden."},{"speaker":"Reporter","gender":"m","text":"Würden Sie den Beruf weiterempfehlen? Ist das ein Beruf fürs Leben?"},{"speaker":"Hubert","gender":"f","text":"Ja, gerne. Für mich ist es ein Beruf fürs Leben! Spannend, Menschen-Kontakt, jeden Tag anders. Aber harte Arbeit, nichts für sensible Leute. Wer Stress mag und Reisen liebt — perfekt."}],"items":[{"q":"Frau Hubert hat Angst vor dem Fliegen.","correct":"ja"},{"q":"Sie kontrolliert nur Tickets, nichts anderes.","correct":"nein"},{"q":"Betrunkene Fahrgäste sind ein häufiges Problem am Wochenende.","correct":"ja"},{"q":"Reisende verstehen meistens, dass Verspätungen nicht ihre Schuld sind.","correct":"nein"},{"q":"Sie empfiehlt den Beruf gerne weiter.","correct":"ja"}]}]};
